// Independent complete enumeration. Field: x^6+x+1; log/antilog arithmetic.
// Subspaces generated by low-pivot RREF; graph maps lifted with high free bits.
// Filters use direct enumeration of surviving 20-bit assignments (no group bitsets).
// No catalogue or result from the primary implementation is read.
#include <algorithm>
#include <array>
#include <cassert>
#include <chrono>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <numeric>
#include <string>
#include <vector>
using namespace std;
using W=uint64_t;
int ex[126],lg[64],iso[64],back_[64],MT[64][64],point_id[1<<18];
int mult(int a,int b){return a&&b?ex[lg[a]+lg[b]]:0;}
int div_(int a,int b){assert(b);return a?ex[(lg[a]-lg[b]+63)%63]:0;}
struct Space {
 array<W,32> p{};vector<int>free;int n;
 Space(int n_=0):n(n_){}
 bool insert(W x){while(x){int t=__builtin_ctzll(x);assert(t<n);if(p[t])x^=p[t];else{p[t]=x;return true;}}return false;}
 W residue(W x)const{for(int t=0;t<n;++t)if(((x>>t)&1)&&p[t])x^=p[t];return x;}
 void finalize(){free.clear();for(int t=n-1;t>=0;--t)if(!p[t])free.push_back(t);}
 W encode(W x)const{x=residue(x);W y=0;for(int k=0;k<(int)free.size();++k)if((x>>free[k])&1)y|=W(1)<<k;return y;}
 W decode(W x)const{W y=0;for(int k=0;k<(int)free.size();++k)if((x>>k)&1)y|=W(1)<<free[k];return y;}
 int dim()const{int r=0;for(W x:p)r+=(x!=0);return r;}
};
vector<int> elements(const vector<int>&b){vector<int>s(1,0);for(int x:b){int n=s.size();for(int k=0;k<n;++k)s.push_back(s[k]^x);}return s;}
int liftq(int x){return ((x&31)<<1)|((x>>5)<<7);}
int qproject(int x){return ((x>>1)&31)|((x>>7)<<5);}
int image12(int x){return iso[x&63]|(iso[x>>6]<<6);}
int pairkey(const vector<int>&b,bool toprimary=false){int p=0,q=0;for(int x:b){if(toprimary)x=back_[x&63]|(back_[x>>6]<<6);int y=qproject(x);if(!y)continue;if(!p)p=y;else if(y!=p&&!q)q=y;else if(q)assert(y==p||y==q||y==(p^q));}assert(p&&q);array<int,3>a{p,q,p^q};sort(a.begin(),a.end());return (a[0]<<10)|a[1];}
struct Core {int key,h,m;};
vector<Core> classify(){
 vector<unsigned char>seen(1<<20);vector<Core>out;int total=0,good=0,covered=0;
 for(int i=0;i<9;++i)for(int j=i+1;j<10;++j){vector<int>pa,qa;for(int k=i+1;k<10;++k)if(k!=j)pa.push_back(k);for(int k=j+1;k<10;++k)qa.push_back(k);
  for(int a=0;a<(1<<(int)pa.size());++a)for(int b=0;b<(1<<(int)qa.size());++b){int p=1<<i,q=1<<j;for(int k=0;k<(int)pa.size();++k)if((a>>k)&1)p|=1<<pa[k];for(int k=0;k<(int)qa.size();++k)if((b>>k)&1)q|=1<<qa[k];++total;
   vector<int>B{1,64,liftq(p),liftq(q)};auto T=elements(B);int cnt[65]={};bool ok=true;int h=0;
   for(int v:T)if(v){int x=v&63,y=v>>6;int id=y?div_(x,y):64;int n=++cnt[id];if(n>3){ok=false;break;}if(n==2)++h;}if(!ok)continue;++good;
   int current=pairkey(B);if(seen[current])continue;vector<int>orb;int canon=1<<30;
   for(int u:T)if(u)for(int v:T)if(v){int det=mult(u&63,v>>6)^mult(u>>6,v&63);if(!det)continue;vector<int>images;
    for(int w:B){int x=div_(mult(v>>6,w&63)^mult(v&63,w>>6),det);int y=div_(mult(u>>6,w&63)^mult(u&63,w>>6),det);images.push_back(x|(y<<6));}
    int key=pairkey(images);orb.push_back(key);canon=min(canon,pairkey(images,true));
   }
   sort(orb.begin(),orb.end());orb.erase(unique(orb.begin(),orb.end()),orb.end());for(int key:orb){assert(!seen[key]);seen[key]=1;++covered;}out.push_back({canon,h,(int)orb.size()});
  }
 }
 assert(total==174251&&good==173786&&covered==good&&out.size()==912);sort(out.begin(),out.end(),[](auto a,auto b){return a.key<b.key;});for(int j=1;j<(int)out.size();++j)assert(out[j-1].key<out[j].key);
 cerr<<"independent RREF catalogue: "<<total<<" normalized, "<<good<<" accepted, "<<out.size()<<" GL2 classes\n";return out;
}
int tr(int x){int y=0;for(int i=0;i<6;++i){y^=x;x=mult(x,x);}assert(y<=1);return y;}
using FMap=array<int,4>;
array<FMap,20> generators(const vector<int>&T,const vector<int>&Z){
 Space Q(12);for(int x:T)Q.insert(x);Q.finalize();assert(Q.dim()==4);
 Space A(32);for(int i=0;i<12;++i){W f=0;int a=i<6?1<<i:0,b=i>=6?1<<(i-6):0;for(int j=0;j<4;++j){int xy=mult(a,Z[j])|(mult(b,Z[j])<<6);f|=Q.encode(xy)<<(8*j);}A.insert(f);}A.finalize();assert(A.dim()==12&&A.free.size()==20);
 array<FMap,20>gen;for(int i=0;i<20;++i){W f=A.decode(W(1)<<i);for(int j=0;j<4;++j)gen[i][j]=Q.decode((f>>(8*j))&255);}return gen;
}
struct Rule {int r,d;array<int,20>g;vector<unsigned char>bad;};
Rule rule(int a,int b,const vector<int>&T,const vector<int>&Z,const array<FMap,20>&gen){
 auto eval=[&](int xy){return mult(a,xy&63)^mult(b,xy>>6);};Space S(6);for(int x:T)S.insert(eval(x));S.finalize();int c=6-S.dim();assert(c>=2&&c<=4);
 Space A(4*c);for(int i=0;i<6;++i){W m=0;for(int j=0;j<4;++j)m|=S.encode(mult(1<<i,Z[j]))<<(c*j);A.insert(m);}A.finalize();Rule R;R.r=S.dim();R.d=A.free.size();
 for(int i=0;i<20;++i){W m=0;for(int j=0;j<4;++j)m|=S.encode(eval(gen[i][j]))<<(c*j);R.g[i]=A.encode(m);}
 R.bad.assign(1<<R.d,0);R.bad[0]=1;if(R.r==2){for(int vector=1;vector<16;++vector)for(int functional=1;functional<16;++functional){W m=0;for(int j=0;j<4;++j)if((functional>>j)&1)m|=W(vector)<<(4*j);R.bad[A.encode(m)]=1;}}
 return R;
}
int dot(int h,int v){return mult(h&63,v&63)^mult((h>>6)&63,(v>>6)&63)^mult(h>>12,v>>12);}
int cross_(int a,int b){return (mult((a>>6)&63,b>>12)^mult(a>>12,(b>>6)&63))|((mult(a>>12,b&63)^mult(a&63,b>>12))<<6)|((mult(a&63,(b>>6)&63)^mult((a>>6)&63,b&63))<<12);}
vector<int>pts;
int verify_object(const vector<int>&B,int&heavy,int&w0,int&w1){
 auto U=elements(B);int cnt[4161]={};heavy=0;for(int v:U)if(v)++cnt[point_id[v]];for(int n:cnt){if(n>3)return 1;heavy+=(n==3);}
 vector<int>lines;for(int h:pts){Space im(6);for(int v:B)im.insert(dot(h,v));if(im.dim()<4){w0=h;return 2;}if(im.dim()==4)lines.push_back(h);}assert(lines.size()==31+4*heavy);
 // Test binary row spaces in the message-coefficient space, not point incidence.
 // Each kernel consists of 16 coefficient vectors. Nonzero intersections forbid spanning.
 vector<array<W,4>>kernels;
 for(int h:lines){array<W,4>bits{};for(int mask=1;mask<256;++mask)if(!dot(h,U[mask]))bits[mask>>6]|=W(1)<<(mask&63);kernels.push_back(bits);}
 for(int i=0;i<(int)lines.size();++i)for(int j=i+1;j<(int)lines.size();++j){bool overlap=false;for(int k=0;k<4;++k)overlap|=(kernels[i][k]&kernels[j][k])!=0;if(!overlap){w0=lines[i];w1=lines[j];return 3;}}
 return 0;
}
int main(int argc,char**argv){
 int lo=argc>1?stoi(argv[1]):0,hi=argc>2?stoi(argv[2]):911;
 int x=1;bool seen[64]={};for(int i=0;i<63;++i){assert(!seen[x]);seen[x]=1;ex[i]=x;lg[x]=i;x<<=1;if(x&64)x^=67;}assert(x==1);for(int i=63;i<126;++i)ex[i]=ex[i-63];for(int a=0;a<64;++a)for(int b=0;b<64;++b)MT[a][b]=mult(a,b);
 for(int a=0;a<64;++a){int x=0;for(int j=5;j>=0;--j)x=mult(x,7)^((a>>j)&1);iso[a]=x;back_[x]=a;}for(int a=0;a<64;++a)assert(back_[iso[a]]==a);
 for(int a=0;a<64;++a)for(int b=0;b<64;++b){int z=0,x=a,y=b;while(y){if(y&1)z^=x;y>>=1;x<<=1;if(x&64)x^=91;}assert(iso[z]==mult(iso[a],iso[b]));}
 auto cores=classify();string tag=to_string(lo)+"_"+to_string(hi);ofstream cat("ind_catalog_"+tag+".csv");cat<<"orbit,a,b,point_weight2,normalized_members\n";for(int j=0;j<(int)cores.size();++j)cat<<j<<','<<(cores[j].key>>10)<<','<<(cores[j].key&1023)<<','<<cores[j].h<<','<<cores[j].m<<'\n';
 // Independent complete scalar orbits of 2D subspaces of F64 (651 objects).
 auto bkey=[&](int a,int b){array<int,3>vv{a,b,a^b};array<int,3>best{999,999,999};for(int u:vv){array<int,3>v;for(int i=0;i<3;++i)v[i]=back_[div_(vv[i],u)];sort(v.begin(),v.end());best=min(best,v);}return best;};
 vector<array<int,3>>types;int planes=0;for(int i=0;i<5;++i)for(int j=i+1;j<6;++j){vector<int>pf,qf;for(int t=i+1;t<6;++t)if(t!=j)pf.push_back(t);for(int t=j+1;t<6;++t)qf.push_back(t);for(int a=0;a<(1<<(int)pf.size());++a)for(int b=0;b<(1<<(int)qf.size());++b){int p=1<<i,q=1<<j;for(int t=0;t<(int)pf.size();++t)if((a>>t)&1)p|=1<<pf[t];for(int t=0;t<(int)qf.size();++t)if((b>>t)&1)q|=1<<qf[t];types.push_back(bkey(p,q));++planes;}}
 sort(types.begin(),types.end());types.erase(unique(types.begin(),types.end()),types.end());assert(planes==651&&types.size()==11);
 int bref[11]={14,2,4,6,8,12,16,20,22,28,36};vector<vector<int>>Zs;for(int k=0;k<11;++k){assert(binary_search(types.begin(),types.end(),bkey(1,iso[bref[k]])));Space s(6);vector<int>Z;for(int v=63;v>=1;--v)if(!tr(v)&&!tr(mult(iso[bref[k]],v)))if(s.insert(v))Z.push_back(v);assert(Z.size()==4);Zs.push_back(Z);}
 // Opposite affine-chart ordering from primary; kernel-based final check.
 for(int x=0;x<64;++x)for(int y=0;y<64;++y)pts.push_back(x|(y<<6)|4096);for(int x=0;x<64;++x)pts.push_back(x|64);pts.push_back(1);
 for(int v=1;v<(1<<18);++v){int x=v&63,y=(v>>6)&63,z=v>>12;point_id[v]=z?64*div_(x,z)+div_(y,z):y?4096+div_(x,y):4160;}
 ofstream out("ind_counts_"+tag+".csv"),sur("ind_survivors_"+tag+".txt");out<<"orbit,k,core_heavy,normal_forms,after_rank34,after_rank2,point_bad,hyperplane_bad,two_span,target\n";long long nall=0,aall=0,ball=0,tall=0;auto start=chrono::steady_clock::now();
 vector<int>remain;remain.reserve(1<<20);
 for(int o=lo;o<=hi;++o){assert(o>=0&&o<912);auto C=cores[o];vector<int>T{1,64,image12(liftq(C.key>>10)),image12(liftq(C.key&1023))};
  for(int k=0;k<11;++k){auto&Z=Zs[k];auto gen=generators(T,Z);vector<Rule>rules;rules.push_back(rule(1,0,T,Z,gen));for(int a=63;a>=0;--a)rules.push_back(rule(a,1,T,Z,gen));stable_sort(rules.begin(),rules.end(),[](auto&a,auto&b){return a.r>b.r;});
   remain.resize(1<<20);iota(remain.begin(),remain.end(),0);array<int,1024>A{},B{};
   for(auto&R:rules){if(R.r==2)continue;for(int m=1;m<1024;++m){int t=__builtin_ctz((unsigned)m),u=m&(m-1);A[m]=A[u]^R.g[t];B[m]=B[u]^R.g[t+10];}size_t n=0;for(int m:remain)if(A[m&1023]!=B[m>>10])remain[n++]=m;remain.resize(n);if(!n)break;}
   long long n1=remain.size();for(auto&R:rules)if(R.r==2&&!remain.empty()){for(int m=1;m<1024;++m){int t=__builtin_ctz((unsigned)m),u=m&(m-1);A[m]=A[u]^R.g[t];B[m]=B[u]^R.g[t+10];}size_t n=0;for(int m:remain)if(!R.bad[A[m&1023]^B[m>>10]])remain[n++]=m;remain.resize(n);}
   long long n2=remain.size(),bad[4]={};for(int m:remain){vector<int>basis=T;FMap f{};for(int i=0;i<20;++i)if((m>>i)&1)for(int j=0;j<4;++j)f[j]^=gen[i][j];for(int j=0;j<4;++j)basis.push_back(f[j]|(Z[j]<<12));int heavy=0,w0=0,w1=0;int r=verify_object(basis,heavy,w0,w1);++bad[r];sur<<o<<' '<<k<<' '<<m<<' '<<r<<' '<<heavy<<' '<<w0<<' '<<w1;for(int v:basis)sur<<' '<<v;sur<<'\n';}
   out<<o<<','<<k<<','<<C.h<<",1048576,"<<n1<<','<<n2<<','<<bad[1]<<','<<bad[2]<<','<<bad[3]<<','<<bad[0]<<'\n';out.flush();nall+=1<<20;aall+=n1;ball+=n2;tall+=bad[0];
  }
  if(o%10==0)cerr<<"independent orbit "<<o<<" stage2 "<<ball<<" targets "<<tall<<" elapsed "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';
 }
 cout<<"normal_forms "<<nall<<" stage1 "<<aall<<" stage2 "<<ball<<" targets "<<tall<<'\n';
}
